    // ── LIFECYCLE ──
    protected override async Task OnInitializedAsync()
    {
        _maTruongBo      = await BrowserStorageService.GetMaTruongBoAsync(JS);
        _selectedNamHoc  = await BrowserStorageService.GetItem(JS, "selectedNamHoc");
        _selectedCapHoc  = await BrowserStorageService.GetItem(JS, "selectedLevel");

        await LoadMetaAndAutoSelect();
    }

    // ── LOAD META + AUTO SELECT KHỐI/LỚP ĐẦU TIÊN ──
    private async Task LoadMetaAndAutoSelect()
    {
        if (string.IsNullOrEmpty(_maTruongBo)) return;

        try
        {
            var taskKhoi = TruongService.hGetDanhSachKhoi(_maTruongBo, _selectedCapHoc ?? "1");
            var taskLop  = TruongService.hGetDanhSachLop(_maTruongBo, _selectedCapHoc ?? "1", _selectedNamHoc ?? "");
            var taskPH   = TruongService.hGetThongTinPhuHuynh(_maTruongBo);

            await Task.WhenAll(taskKhoi, taskLop, taskPH);

            _khoiList    = taskKhoi.Result;
            _allLopList  = taskLop.Result;
            _allParents  = taskPH.Result;

            // Auto select khối đầu tiên
            if (_khoiList.Any())
            {
                _selectedMaKhoi = _khoiList[0].MaKhoiBo ?? "";
                _lopFilteredList = _allLopList
                    .Where(l => l.MaKhoiBo == _selectedMaKhoi)
                    .ToList();
            }
            else
            {
                _lopFilteredList = _allLopList.ToList();
            }

            // Auto select lớp đầu tiên → load học sinh
            if (_lopFilteredList.Any())
            {
                _selectedMaLop = _lopFilteredList[0].MaLopBo ?? "";
                await LoadStudents();
            }
        }
        catch (Exception ex)
        {
            Console.WriteLine($"LoadMeta error: {ex.Message}");
        }
    }

    // ── LOAD HỌC SINH THEO LỚP ──
    private async Task LoadStudents()
    {
        if (string.IsNullOrEmpty(_maTruongBo) || string.IsNullOrEmpty(_selectedMaLop)) return;

        _isLoading = true;
        _allStudents = new();
        _filteredList = new();
        StateHasChanged();

        try
        {
            var raw = await TruongService.hGetHocSinhByLop(
                _maTruongBo, _selectedMaLop, _selectedNamHoc ?? "");

            var maHsSet = raw.Select(s => s.MaHsSo).ToHashSet();
            var parentsInClass = _allParents
                .Where(p => maHsSet.Contains(p.MaHocSinhSo))
                .ToList();

            _allStudents = raw.Select(s =>
            {
                var ph = parentsInClass.Where(p => p.MaHocSinhSo == s.MaHsSo).ToList();
                return new StudentVM
                {
                    Hs  = s,
                    Cha = ph.FirstOrDefault(p => IsCha(p.QuanHe)),
                    Me  = ph.FirstOrDefault(p => IsMe(p.QuanHe))
                };
            }).ToList();

            ApplyFilter();
        }
        catch (Exception ex)
        {
            Console.WriteLine($"LoadStudents error: {ex.Message}");
        }
        finally
        {
            _isLoading = false;
            StateHasChanged();
        }
    }

    // ── FILTER ──
    private void ApplyFilter()
    {
        if (string.IsNullOrWhiteSpace(_searchTerm))
        {
            _filteredList = _allStudents.ToList();
        }
        else
        {
            var t = _searchTerm.Trim();
            _filteredList = _allStudents.Where(vm =>
                (vm.Hs.HoTen?.Contains(t, StringComparison.OrdinalIgnoreCase) == true) ||
                (vm.Hs.MaBo?.Contains(t, StringComparison.OrdinalIgnoreCase) == true) ||
                (vm.Hs.MaHsSo?.Contains(t, StringComparison.OrdinalIgnoreCase) == true)
            ).ToList();
        }
        _currentPage = 1;
        BuildPagedList();
        StateHasChanged();
    }

    private void BuildPagedList()
    {
        _displayList = _filteredList
            .Skip((_currentPage - 1) * _pageSize)
            .Take(_pageSize)
            .ToList();
    }

    // ── PAGINATION HANDLERS ──
    private void OnPageChanged(int page)
    {
        _currentPage = page;
        BuildPagedList();
        StateHasChanged();
    }

    private void OnPageSizeChanged(int size)
    {
        _pageSize    = size;
        _currentPage = 1;
        BuildPagedList();
        StateHasChanged();
    }

    // ── FILTER EVENTS ──
    private async Task OnKhoiChanged(ChangeEventArgs e)
    {
        _selectedMaKhoi = e.Value?.ToString() ?? "";
        _lopFilteredList = string.IsNullOrEmpty(_selectedMaKhoi)
            ? _allLopList.ToList()
            : _allLopList.Where(l => l.MaKhoiBo == _selectedMaKhoi).ToList();

        // Auto select lớp đầu tiên mới
        _selectedMaLop = _lopFilteredList.FirstOrDefault()?.MaLopBo ?? "";
        _searchTerm = "";
        await LoadStudents();
    }

    private async Task OnLopChanged(ChangeEventArgs e)
    {
        _selectedMaLop = e.Value?.ToString() ?? "";
        _searchTerm = "";
        await LoadStudents();
    }

    // ── MODAL ──
    private void OpenDetail(StudentVM vm)
    {
        _detailVm   = vm;
        _showDetail = true;
    }

    private void CloseDetail()
    {
        _showDetail = false;
        _detailVm   = null;
    }

    // ── AVATAR STATE ──
    private HocSinhDTO?   _avatarTarget      = null;
    private bool          _showAvatarModal   = false;
    private IBrowserFile? _selectedAvatarFile = null;
    private string?       _previewUrl        = null;
    private string        _avatarFileError   = "";
    private bool          _isSavingAvatar    = false;
    private bool          _forceReloadAvatar = false;

    private string GetAvatarUrl(HocSinhDTO hs)
    {
        if (string.IsNullOrWhiteSpace(_maTruongBo) || string.IsNullOrWhiteSpace(hs.MaHsSo))
            return "../image/avtmacdinh.jpg";
        var url = $"https://face.titkul.com/ImageFace/{_maTruongBo}/{hs.MaHsSo}.jpg";
        return _forceReloadAvatar ? $"{url}?v={DateTime.Now.Ticks}" : url;
    }

    private void OpenAvatarModal(HocSinhDTO hs)
    {
        _avatarTarget       = hs;
        _selectedAvatarFile = null;
        _previewUrl         = null;
        _avatarFileError    = "";
        _showAvatarModal    = true;
    }

    private void CloseAvatarModal()
    {
        _showAvatarModal    = false;
        _avatarTarget       = null;
        _selectedAvatarFile = null;
        _previewUrl         = null;
        _avatarFileError    = "";
    }

    private async Task OnAvatarFileSelected(InputFileChangeEventArgs e)
    {
        _avatarFileError    = "";
        _selectedAvatarFile = null;
        _previewUrl         = null;

        var file = e.File;
        var ext  = Path.GetExtension(file.Name).ToLowerInvariant();
        if (ext != ".jpg" && ext != ".jpeg")
        {
            _avatarFileError = "Chỉ chấp nhận file JPG/JPEG!";
            return;
        }
        const long maxBytes = 100 * 1024;
        if (file.Size > maxBytes)
        {
            _avatarFileError = $"File quá lớn ({file.Size / 1024} KB). Chọn ảnh nhỏ hơn 100 KB.";
            return;
        }
        _selectedAvatarFile = file;
        try
        {
            await using var stream = file.OpenReadStream(maxBytes);
            using var ms = new MemoryStream();
            await stream.CopyToAsync(ms);
            _previewUrl = $"data:image/jpeg;base64,{Convert.ToBase64String(ms.ToArray())}";
        }
        catch (Exception ex)
        {
            _previewUrl      = null;
            _avatarFileError = "Đã xảy ra lỗi, vui lòng thử lại!";
        }
    }

    private async Task SaveNewAvatar()
    {
        if (_avatarTarget == null || _selectedAvatarFile == null) return;
        _isSavingAvatar = true;
        StateHasChanged();
        try
        {
            using var content = new MultipartFormDataContent();
            const long maxStream = 100 * 1024;
            var stream      = _selectedAvatarFile.OpenReadStream(maxStream);
            var fileContent = new StreamContent(stream);
            fileContent.Headers.ContentType =
                new System.Net.Http.Headers.MediaTypeHeaderValue("image/jpeg");
            content.Add(fileContent, "\"file\"", _selectedAvatarFile.Name);

            var url = $"https://upload-face.titkul.edu.vn/service_uploadFace/upload" +
                      $"?matruongbo={Uri.EscapeDataString(_maTruongBo ?? "")}" +
                      $"&ma_user={Uri.EscapeDataString(_avatarTarget.MaHsSo ?? "")}" +
                      $"&ho_ten={Uri.EscapeDataString(_avatarTarget.HoTen ?? "")}";

            var response = await httpClient.PostAsync(url, content);
            if (response.IsSuccessStatusCode)
            {
                _forceReloadAvatar = true;
                CloseAvatarModal();
            }
            else
            {
                _avatarFileError = $"Lỗi server ({(int)response.StatusCode}). Vui lòng thử lại.";
            }
        }
        catch (Exception ex) { _avatarFileError = "Đã xảy ra lỗi, vui lòng thử lại!"; }
        finally
        {
            _isSavingAvatar = false;
            StateHasChanged();
        }
    }



