    // ── UTILS ──
    private static bool IsCha(string? q)
    {
        if (string.IsNullOrEmpty(q)) return false;
        var s = q.ToLowerInvariant();
        return s.Contains("cha") || s.Contains("bố") || s.Contains("bo") || s.Contains("father");
    }

    private static bool IsMe(string? q)
    {
        if (string.IsNullOrEmpty(q)) return false;
        var s = q.ToLowerInvariant();
        return s.Contains("mẹ") || s.Contains("me") || s.Contains("mau") || s.Contains("mother");
    }

